namespace WallstopStudios.UnityHelpers.Tests.Editor.Capture
{
#if UNITY_EDITOR
    using System;
    using System.IO;
    using NUnit.Framework;
    using UnityEditor;
    using UnityEditor.UIElements;
    using UnityEngine;
    using UnityEngine.UIElements;
    using WallstopStudios.UnityHelpers.Editor.Tools;
    using WallstopStudios.UnityHelpers.Tests.Core;

    [TestFixture]
    public sealed class MemberPolicyCaptureTests : CommonTestBase
    {
        [Test]
        public void CaptureMemberPolicy()
        {
            Assert.That(
                EditorSurfaceCapture.IsSupported,
                Is.True,
                EditorSurfaceCapture.UnsupportedReason
            );
            string phase = Environment.GetEnvironmentVariable("UH_MEMBER_CAPTURE_PHASE");
            string output = Environment.GetEnvironmentVariable("UH_MEMBER_CAPTURE_OUTPUT");
            Assert.That(output, Is.Not.Null.And.Not.Empty);
            string ruleset = Path.Combine(Application.dataPath, "MemberPolicyCapture.ruleset");
            Assert.That(File.Exists(ruleset), Is.False);
            AnalyzerPolicyWindow window = Track(
                ScriptableObject.CreateInstance<AnalyzerPolicyWindow>()
            );
            window.RulesetPathOverride = ruleset;
            window.BuildUserInterface();
            ToolbarSearchField search = window.rootVisualElement.Q<ToolbarSearchField>();
            search.RegisterCallback<AttachToPanelEvent>(_ => search.value = "WUH029");
            bool hasRow = window.GetPolicyRow("WUH029") != null;
            Assert.That(hasRow, Is.EqualTo(phase == "after"));
            VisualElement surface = new VisualElement();
            surface.style.width = 1000;
            surface.style.height = 600;
            surface.style.backgroundColor = EditorGUIUtility.isProSkin
                ? new Color(0.22f, 0.22f, 0.22f)
                : new Color(0.76f, 0.76f, 0.76f);
            window.rootVisualElement.style.flexGrow = 1;
            surface.Add(window.rootVisualElement);
            EditorSurfaceCaptureResult result = EditorSurfaceCapture.Capture(
                surface,
                1000,
                600,
                output
            );
            Assert.That(
                window.GetPolicyRow("WUH001").style.display.value,
                Is.EqualTo(DisplayStyle.None)
            );
            Assert.That(result.DistinctColorCount, Is.GreaterThan(16));
            Assert.That(result.OnlyCursorRectErrors, Is.True, result.RenderErrorSummary);
            Assert.That(File.Exists(ruleset), Is.False);
            File.WriteAllText(
                output + ".txt",
                result
                    + "\nphase="
                    + phase
                    + "\nmodule="
                    + typeof(AnalyzerPolicyWindow).Module.ModuleVersionId
                    + "\nhasRow="
                    + hasRow
            );
        }
    }
#endif
}

